#pragma warning disable CS8601 // Possible null reference assignment.#pragma warning disable CS8604 // Possible null reference argument.using System.Collections.Generic;using System.Diagnostics;using Microsoft.CodeAnalysis;using System.Linq;using FirstGearGames.Roslyn.CodeBuilding;using FirstGearGames.Roslyn.Extensions;using FirstGearGames.Roslyn.FishNet.Constants;using FirstGearGames.Roslyn.FishNet.Helpers;using FirstGearGames.Roslyn.Native.Constants;namespace FirstGearGames.Roslyn.FishNet.CodeBuilding{    public enum AddSerializerType    {        Unset,        Full,        Delta,    }    public enum GetSerializerType    {        Full,        Delta,        FavorFull,        FavorDelta,    }    public class Serializers    {        //Writers.        private readonly Dictionary<string, SerializerMethod> _writeMethods = new();        private readonly Dictionary<string, SerializerMethod> _writeDeltaMethods = new();        //Readers        private readonly Dictionary<string, SerializerMethod> _readMethods = new();        private readonly Dictionary<string, SerializerMethod> _readDeltaMethods = new();        //Consts.        public const string Generated_ValueParameter_Prefix = "value";        public void Initialize(IAssemblySymbol runtimeAssemblySymbol)        {            Log("");            Log($"Initialize.");            AddDefaultWriteMethods(runtimeAssemblySymbol);            AddDefaultReadMethods(runtimeAssemblySymbol);        }        #region Add/get serializers        /// <summary>        /// Adds to writers.        /// </summary>        public void AddWriteMethod(SerializerMethod sm, AddSerializerType addType)        {            Dictionary<string, SerializerMethod> dict = (addType == AddSerializerType.Full) ? _writeMethods : _writeDeltaMethods;            if (dict.ContainsKey(sm.TypeFullName))            {                Log($"{addType} writer already exists for {sm.TypeFullName}.");            }            else            {                dict[sm.TypeFullName] = sm;                Log($"Added {addType} writer method {sm.MethodName} for {sm.TypeFullName}.");            }        }        /// <summary>        /// Adds to readers.        /// </summary>        public void AddReadMethod(SerializerMethod sm, AddSerializerType addType)        {            Dictionary<string, SerializerMethod> dict = (addType == AddSerializerType.Full) ? _readMethods : _readDeltaMethods;            if (dict.ContainsKey(sm.TypeFullName))            {                Log($"{addType} reader method already exists for {sm.TypeFullName}.");            }            else            {                dict[sm.TypeFullName] = sm;                Log($"Added {addType} reader method {sm.MethodName} for {sm.TypeFullName}.");            }        }        /// <summary>        /// Returns if a write method exists for a full name.        /// </summary>        public bool GetWriteMethodExists(string typeFullName, GetSerializerType getType)        {            SerializerMethod sm = GetWriteMethod(typeFullName, getType);            return sm.IsValid();        }        /// <summary>        /// Returns a writer.        /// </summary>        public SerializerMethod GetWriteMethod(string typeFullName, GetSerializerType getType) => GetSerializerMethod(typeFullName, getType, writer: true);        /// <summary>        /// Returns a reader.        /// </summary>        public SerializerMethod GetWriteMethod(ITypeSymbol typeSymbol, GetSerializerType getType, bool metadataName)        {            //Try to get the read method for the exact name.            string typeFullName = typeSymbol.GetTypeSymbolFullNameWithGenericArguments(metadataName);            SerializerMethod result = GetSerializerMethod(typeFullName, getType, writer: true);            /* If not found then see if there are generic arguments.             * Should there be generic arguments get the unnamed version             * of the arguments and check for a reader. */            if (!result.IsValid())            {                if (typeSymbol is IArrayTypeSymbol)                {                    result = GetSerializerMethod(NativeConstants.GenericArray_FullName, getType, writer: true);                }                else                {                    if (typeSymbol is INamedTypeSymbol { IsGenericType: true })                    {                        /* This should return named arguments as typeSymbol                         * is not expected to be generic. If this does                         * return unspecified generics that's fine as well since                         * that's what we want to convert to anyway. */                        List<string> genericArguments = typeSymbol.GetGenericArgumentsString();                        for (int i = 0; i < genericArguments.Count; i++)                            genericArguments[i] = $"{NativeConstants.GeneralParameter_Name}{i}";                        string fullName = typeSymbol.GetSymbolFullName(metadataName: false);                        string generics = genericArguments.GetCombinedGenericArguments(typeSymbol);                        result = GetSerializerMethod($"{fullName}{generics}", getType, writer: true);                    }                }            }            return result;        }        /// <summary>        /// Tries to find a full write serializer method. If not found, returns a new serializer method which uses the generic method.        /// </summary>        /// <param name="found">True if method was found; false if generic serializer method is use.</param>        public SerializerMethod GetFullWriteSerializerMethod(ITypeSymbol typeSymbol, out bool found)        {            //The full generic name can be             string typeFullNameWithGenerics = typeSymbol.GetTypeSymbolFullNameWithGenericArguments(metadataName: false);            //Get serializer method for the field.            SerializerMethod sm = GetWriteMethod(typeSymbol, GetSerializerType.Full, metadataName: false) as SerializerMethod;            //If serializer method is not found then try again with generics specified.            if (!sm.IsValid())                GetWriteMethodExists(typeFullNameWithGenerics, GetSerializerType.Full);            found = sm.IsValid();            //If serializer is still not found then note it and call Write<>.            if (!found)                sm = CreateWriteSerializerMethod(typeSymbol, metadataName: false);            return sm;        }        /// <summary>        /// Returns if a write method exists for a full name.        /// </summary>        public bool GetReadMethodExists(string typeFullName, GetSerializerType getType)        {            SerializerMethod sm = GetReadMethod(typeFullName, getType);            return sm.IsValid();        }        /// <summary>        /// Returns a reader.        /// </summary>        public SerializerMethod GetReadMethod(string typeFullName, GetSerializerType getType) => GetSerializerMethod(typeFullName, getType, writer: false);        /// <summary>        /// Returns a reader.        /// </summary>        public SerializerMethod GetReadMethod(ITypeSymbol typeSymbol, GetSerializerType getType, bool metadataName)        {            //Try to get the read method for the exact name.            string typeFullName = typeSymbol.GetTypeSymbolFullNameWithGenericArguments(metadataName);            SerializerMethod result = GetSerializerMethod(typeFullName, getType, writer: false);            /* If not found then see if there are generic arguments.             * Should there be generic arguments get the unnamed version             * of the arguments and check for a reader. */            if (!result.IsValid())            {                if (typeSymbol is IArrayTypeSymbol)                {                    result = GetSerializerMethod(NativeConstants.GenericArray_FullName, getType, writer: false);                }                else                {                    if (typeSymbol is INamedTypeSymbol { IsGenericType: true })                    {                        /* This should return named arguments as typeSymbol                         * is not expected to be generic. If this does                         * return unspecified generics that's fine as well since                         * that's what we want to convert to anyway. */                        List<string> genericArguments = typeSymbol.GetGenericArgumentsString();                        for (int i = 0; i < genericArguments.Count; i++)                            genericArguments[i] = $"{NativeConstants.GeneralParameter_Name}{i}";                        string fullName = typeSymbol.GetSymbolFullName(metadataName: false);                        string generics = genericArguments.GetCombinedGenericArguments(typeSymbol);                        result = GetSerializerMethod($"{fullName}{generics}", getType, writer: false);                    }                }            }            return result;        }        /// <summary>        /// Returns if a write method exists for a full name.        /// </summary>        public bool GetSerializerMethodExists(string typeFullName, GetSerializerType getType, bool writer)        {            if (writer)                return GetWriteMethodExists(typeFullName, getType);            else                return GetReadMethodExists(typeFullName, getType);        }        /// <summary>        /// Returns a reader or writer.        /// </summary>        private SerializerMethod GetSerializerMethod(string typeFullName, GetSerializerType getType, bool writer)        {            SerializerMethod result = null;            if (getType == GetSerializerType.Full)            {                Dictionary<string, SerializerMethod> dict = (writer) ? _writeMethods : _readMethods;                dict.TryGetValue(typeFullName, out result);//                Log($"Result valid {result.IsValid()} for {typeFullName}. Name {result?.MethodName}");            }            else if (getType == GetSerializerType.Delta)            {                Dictionary<string, SerializerMethod> dict = (writer) ? _writeDeltaMethods : _readDeltaMethods;                dict.TryGetValue(typeFullName, out result);            }            else if (getType == GetSerializerType.FavorFull || getType == GetSerializerType.FavorDelta)            {                Dictionary<string, SerializerMethod> dictA;                Dictionary<string, SerializerMethod> dictB;                if (getType == GetSerializerType.FavorFull)                {                    dictA = (writer) ? _writeMethods : _readMethods;                    dictB = (writer) ? _writeDeltaMethods : _readDeltaMethods;                }                else                {                    dictA = (writer) ? _writeDeltaMethods : _readDeltaMethods;                    dictB = (writer) ? _writeMethods : _readMethods;                }                //Try A first, then B.                if (!dictA.TryGetValue(typeFullName, out result))                    dictB.TryGetValue(typeFullName, out result);            }            else            {                Log($"SerializerType {getType} is unhandled.");            }            if (result == null)                result = new();            // if (result == null)             // {            //                 //     Log($"<-------------- start for {typeFullName}. Writers count {_writeMethods.Count}. DeltaWriters count {_writeDeltaMethods.Count}");            //            //     foreach (KeyValuePair<string,SerializerMethod> serializerMethod in _writeMethods)            //         Log($"WriteMethods SM: {serializerMethod.Key}");            //            //            //     foreach (KeyValuePair<string,SerializerMethod> serializerMethod in _writeDeltaMethods)            //         Log($"WriteDeltaMethods SM: {serializerMethod.Key}");            //            //                 // }            return result;        }        /// <summary>        /// Returns the collection containing all delta writers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethod> GetWriteMethods() => _writeMethods;        /// <summary>        /// Returns the collection containing all delta writers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethod> GetWriteDeltaMethods() => _writeDeltaMethods;        /// <summary>        /// Returns the collection containing all delta readers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethod> GetReadMethods() => _readMethods;        /// <summary>        /// Returns the collection containing all delta readers.        /// </summary>        public IReadOnlyDictionary<string, SerializerMethod> GetReadDeltaMethods() => _readDeltaMethods;        #endregion        /// <summary>        /// Creates a SerializerMethod for Write<T>.        /// </summary>        public SerializerMethod CreateWriteSerializerMethod(ITypeSymbol typeSymbol, bool metadataName)        {            string typeFullNameWithGenerics = typeSymbol.GetTypeSymbolFullNameWithGenericArguments(metadataName);            return new SerializerMethod(typeSymbol, $"{FishNetConstants.Writer_Write_Name}<{typeFullNameWithGenerics}>");        }        /// <summary>        /// Adds default normal writers.        /// </summary>        private void AddDefaultWriteMethods(IAssemblySymbol runtimeAssemblySymbol)        {            Log("");            Log("AddDefaultWriteMethods");            if (!runtimeAssemblySymbol.GetINamedTypeSymbol(FishNetConstants.Writer_FullName, out INamedTypeSymbol? nameTypeSymbol)) return;            if (nameTypeSymbol == null) return;            const bool isMetadataName = false;            //  Log($"<< Symbols count is {nameTypeSymbol.GetMembers().OfType<IMethodSymbol>().Count()}");            foreach (IMethodSymbol methodSymbol in nameTypeSymbol.GetMembers().OfType<IMethodSymbol>())            {                AddSerializerType addType = AddSerializerType.Unset;                //Full write.                if (methodSymbol.HasAttribute(FishNetConstants.DefaultWriterAttribute_FullName, isMetadataName, out _))                    addType = AddSerializerType.Full;                //Delta write.                else if (methodSymbol.HasAttribute(FishNetConstants.DefaultDeltaWriterAttribute_FullName, isMetadataName, out _))                    addType = AddSerializerType.Delta;                bool isDelta = (addType == AddSerializerType.Delta);                int expectedParameters = (isDelta) ? 3 : 1;                //Check for incorrect parameter count.                if (expectedParameters != methodSymbol.Parameters.Length)                    addType = AddSerializerType.Unset;                if (addType != AddSerializerType.Unset)                    AddWriteMethod(new DeltaSerializerMethod(methodSymbol.Parameters[0].Type, methodSymbol.Name), addType);            }        }        /// <summary>        /// Adds default normal writers.        /// </summary>        private void AddDefaultReadMethods(IAssemblySymbol runtimeAssemblySymbol)        {            Log("");            Log("AddDefaultReadMethods");            if (!runtimeAssemblySymbol.GetINamedTypeSymbol(FishNetConstants.Reader_FullName, out INamedTypeSymbol? nameTypeSymbol)) return;            if (nameTypeSymbol == null) return;            const bool isMetadataName = false;            foreach (IMethodSymbol methodSymbol in nameTypeSymbol.GetMembers().OfType<IMethodSymbol>())            {                SerializerMethod sm = default;                AddSerializerType addType = AddSerializerType.Unset;                //Full.                // Log($"AAAA A {methodSymbol.ReturnType.Kind}");                if (methodSymbol.HasAttribute(FishNetConstants.DefaultReaderAttribute_FullName, isMetadataName, out _))                {                    sm = new SerializerMethod(methodSymbol.ReturnType, methodSymbol.Name);                    addType = AddSerializerType.Full;                }                //Delta.                else if (methodSymbol.HasAttribute(FishNetConstants.DefaultDeltaReaderAttribute_FullName, isMetadataName, out _))                {                    sm = new DeltaSerializerMethod(methodSymbol.ReturnType, methodSymbol.Name);                    addType = AddSerializerType.Delta;                }                bool isDelta = (addType == AddSerializerType.Delta);                int expectedParameters = (isDelta) ? 1 : 0;                //Check for incorrect parameter count.                if (expectedParameters != methodSymbol.Parameters.Length)                    addType = AddSerializerType.Unset;                if (addType != AddSerializerType.Unset)                    AddReadMethod(sm, addType);            }        }        /// <summary>        /// Returns the typeSymbol as a generic collection name, if it's a collection.        /// For example: MyType[] will return T[].        /// </summary>        public string GetGenericCollectionName(ITypeSymbol typeSymbol, out bool isGenericCollection)        {            if (typeSymbol is IArrayTypeSymbol)            {                isGenericCollection = true;                return $"{NativeConstants.GenericArray_FullName}";            }            //Check for list.            else            {                if (typeSymbol is INamedTypeSymbol { IsGenericType: true } namedTypeSymbol)                {                    string namedFullName = namedTypeSymbol.GetSymbolFullName(metadataName: false);                    if (namedFullName == NativeConstants.List_FullName)                    {                        isGenericCollection = true;                        return NativeConstants.GenericList_FullName;                    }                }            }            isGenericCollection = false;            return string.Empty;        }        /// <summary>        /// Returns the parameter name used for values within a generated delta writer.        /// </summary>        public string GetValueParameterName(int parameterIndex) => $"{Generated_ValueParameter_Prefix}{parameterIndex}";        /// <summary>        /// Gets fields which can be serialized over the network.        /// </summary>        public List<IFieldSymbol> GetSerializableFieldSymbols(ITypeSymbol? typeSymbol)        {            List<IFieldSymbol> results = new();            if (typeSymbol == null) return results;            if (typeSymbol is not INamedTypeSymbol namedTypeSymbol) return results;            //Call write for all members.            foreach (ISymbol symbol in namedTypeSymbol.GetMembers())            {                IFieldSymbol? fieldSymbol = symbol as IFieldSymbol;                if (fieldSymbol == null) continue;                if (!CanSerializeFieldSymbol(fieldSymbol)) continue;                results.Add(fieldSymbol);            }            return results;        }        /// <summary>        /// Gets fields which can be serialized over the network.        /// </summary>        /// <param name="namedTypeSymbol"></param>        /// <returns></returns>        public List<IFieldSymbol> GetSerializableFieldSymbols(INamedTypeSymbol? namedTypeSymbol)        {            List<IFieldSymbol> results = new();            if (namedTypeSymbol == null) return results;            //Call write for all members.            foreach (ISymbol symbol in namedTypeSymbol.GetMembers())            {                IFieldSymbol? fieldSymbol = symbol as IFieldSymbol;                if (fieldSymbol == null) continue;                if (!CanSerializeFieldSymbol(fieldSymbol)) continue;                results.Add(fieldSymbol);            }            return results;        }        /// <summary>        /// Returns if a serializer can be generated for a symbol.        /// </summary>        public bool CanSerializeNamedTypeSymbol(INamedTypeSymbol? symbol)        {            if (symbol == null) return false;            if (symbol.IsReadOnly || symbol.IsAbstract || symbol.IsSealed || symbol.IsExtern || symbol.DeclaredAccessibility != Accessibility.Public) return false;            if (symbol.HasAttribute(FishNetConstants.ExcludeSerializationAttribute_FullName, isMetadataName: false)) return false;            return true;        }        /// <summary>        /// Returns true if a symbol can have a serializer generated for it.        /// </summary>        private bool CanSerializeFieldSymbol(IFieldSymbol? symbol)        {            if (symbol == null) return false;            if (symbol.IsReadOnly || symbol.IsAbstract || symbol.IsSealed || symbol.IsConst || symbol.IsExtern || symbol.DeclaredAccessibility != Accessibility.Public) return false;            return true;        }        /// <summary>        /// Returns if a type qualifies for a delta serializer.        /// </summary>        private bool CanCreateSerializer_Internal(INamedTypeSymbol? namedTypeSymbol)        {            if (namedTypeSymbol == null)                return false;            //Not a supported type. Must be a user defined struct or class.            if (!namedTypeSymbol.IsUserDefinedClassOrStruct())                return false;            return true;        }        /// <summary>        /// Returns if a type qualifies for a serializer.        /// </summary>        public bool CanCreateSerializer(INamedTypeSymbol? namedTypeSymbol)        {            return CanCreateSerializer_Internal(namedTypeSymbol);            return true;        }        /// <summary>        /// Returns if a type qualifies for a delta serializer.        /// </summary>        public bool CanCreateDeltaSerializer(INamedTypeSymbol? namedTypeSymbol)        {            if (!CanCreateSerializer_Internal(namedTypeSymbol))                return false;            int memberCount = namedTypeSymbol.MemberNames.Count();            //Too many parameters to process as a delta writer due to not enough flags.            const int maxMemberCount = 62;            if (memberCount >= maxMemberCount)                return false;            return true;        }        private void Log(string txt)        {            if (txt.Length == 0)                Debugg.Log(txt);            else                Debugg.Log($"   [Serializers] {txt}");        }    }}